/// pre: Self, post: Self, params...
fn pre_post_params(params: &Vec<TransitionParam>) -> TokenStream {
    let params: Vec<TokenStream> = params
        .iter()
        .map(|param| {
            let ident = &param.name;
            let ty = &param.ty;
            quote! { #ident: #ty }
        })
        .collect();
    return quote! {
        pre: Self,
        post: Self,
        #(#params),*
    };
}

